import {GLOSSARY,searchGlossary,WIKI_SOURCES,WIKI_PATHS} from './glossary.js';
import {statIcon} from './stat-view.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const WIKI_CATEGORIES=['자금','고객','제품','조직','기업·전략','투자','투자자·지원','투자계약'];
const categoryIndex=category=>WIKI_CATEGORIES.indexOf(category);
const termButton=id=>{const term=GLOSSARY.find(t=>t.id===id);return term?`<button class="wiki-term-chip" data-action="wiki-term" data-id="${term.id}">${esc(term.term)}</button>`:'';};
export function wikiCards(query='',category='all'){
 const terms=searchGlossary(query,category);
 return `<p class="wiki-result-count" role="status">${query?`‘${esc(query)}’ 검색 결과`:'용어'} <b>${terms.length}</b>개</p>${terms.length?terms.map(t=>`<button class="card wiki-card" data-action="wiki-term" data-id="${t.id}" data-category="${categoryIndex(t.category)}"><span class="wiki-category-tag">${t.category}</span><h2>${esc(t.term)}</h2><p>${esc(t.definition)}</p><span class="wiki-card-detail">설명·예시 보기</span></button>`).join(''):'<div class="wiki-empty"><p>검색 결과가 없어요.</p><span>한글 용어 또는 영어 약어로 검색해 보세요.</span><button class="quiet" data-action="wiki-reset">전체 용어 보기</button></div>'}`;
}
export function wikiView(query='',category='all'){
 return `<button class="primary wiki-match-launch" data-action="wiki-match">↔ 용어 짝맞추기</button><section class="wiki-intro"><div>${statIcon('book')}<p><strong>뜻을 알고, 선택에 써먹기</strong><span>${GLOSSARY.length}개 용어 · 쉬운 설명, 예시, 게임 속 맥락</span></p></div><details class="wiki-resources"><summary>참고 용어집</summary><p>용어별 참고 자료는 상세 화면에서 확인할 수 있어요. 예시와 게임 설명은 이 게임에 맞게 작성했어요.</p><a href="${WIKI_SOURCES.vcs.url}" target="_blank" rel="noopener noreferrer">${WIKI_SOURCES.vcs.name}</a><a href="${WIKI_SOURCES.gsva.url}" target="_blank" rel="noopener noreferrer">함께 볼 자료 · ${WIKI_SOURCES.gsva.name}</a></details></section><section class="wiki-learning-paths" aria-label="상황별 추천 용어">${WIKI_PATHS.map(path=>`<details><summary>${path.title}</summary><div>${path.terms.map(termButton).join('')}</div></details>`).join('')}</section><div class="wiki-tools"><label class="sr-only" for="wiki-search">창업 용어 검색</label><input class="field" id="wiki-search" type="search" placeholder="용어·약어·설명 검색 · 예: 런웨이, SAFE" value="${esc(query)}"><div class="wiki-filters" aria-label="용어 분야">${['all',...WIKI_CATEGORIES].map(c=>`<button data-action="wiki-category" data-id="${c}" data-category="${categoryIndex(c)}" class="${c===category?'selected':''}" aria-pressed="${c===category}">${c==='all'?'전체':c}</button>`).join('')}</div></div><div class="wiki-grid" id="wiki-cards">${wikiCards(query,category)}</div>`;
}
export function termDetail(id){
 const t=GLOSSARY.find(t=>t.id===id);if(!t)return null;
 return {title:t.term,body:`<article class="wiki-detail" data-category="${categoryIndex(t.category)}"><div class="wiki-detail-meta"><span class="wiki-category-tag">${t.category}</span>${t.english?`<span>${esc(t.english)}</span>`:''}</div><p class="wiki-definition">${esc(t.definition)}</p><p class="wiki-explanation">${esc(t.detail)}</p>${t.formula?`<div class="wiki-formula"><span>계산해 보면</span><p>${esc(t.formula)}</p></div>`:''}<section class="wiki-example"><h3>예를 들면</h3><p>${esc(t.example)}</p></section><section class="wiki-game-context"><h3>${statIcon('hobby')} 게임에서는</h3><p>${esc(t.game)}</p></section><section class="wiki-distinction"><h3>헷갈리지 않기</h3><p>${esc(t.pitfall)}</p></section><section class="wiki-related"><h3>같이 보면 좋은 용어</h3><div>${(t.related||[]).map(termButton).join('')}</div></section><footer class="wiki-source">${t.source?`<span>참고 자료 · 뜻을 쉽게 풀어 썼어요.</span><a href="${esc(t.source.url)}" target="_blank" rel="noopener noreferrer">${esc(t.source.name)} · 원문 보기</a>`:'<span>게임용 기초 해설 · 수치 예시는 이해를 위한 가정이에요.</span>'}</footer></article>`};
}
